async function callBedrock(prompt: string, isJson: boolean = false) {
  if (!bedrockClient) {
    throw new Error('AWS credentials for Bedrock are not configured.');
  }

  // Define Claude 3.5 Haiku parameters. (We can also use claude-3-haiku-20240307-v1:0 if 3.5 is unavailable, but ap-south-1 has 3.5 Haiku as anthropic.claude-3-5-haiku-20241022-v1:0)
  // According to AWS Bedrock documentation for Claude 3 models, the payload format is:
  const payload = {
    anthropic_version: "bedrock-2023-05-31",
    max_tokens: 2000,
    messages: [
      {
        role: "user",
        content: [
          {
            type: "text",
            text: prompt + (isJson ? "\n\nPlease output ONLY valid JSON without any markdown formatting." : "")
          }
        ]
      }
    ],
    temperature: 0.7
  };

  const command = new InvokeModelCommand({
    modelId: "anthropic.claude-3-5-haiku-20241022-v1:0",
    contentType: "application/json",
    accept: "application/json",
    body: JSON.stringify(payload)
  });

  try {
    const response = await bedrockClient.send(command);
    const responseBody = JSON.parse(new TextDecoder().decode(response.body));
    const responseText = responseBody.content?.[0]?.text || '';
    return responseText.trim();
  } catch (error: any) {
    // Fallback to claude-3-haiku if 3.5 haiku is not available in region
    if (error.name === 'ValidationException' || error.message?.includes('not found') || error.name === 'ResourceNotFoundException') {
      console.log('Claude 3.5 Haiku not found or not enabled, falling back to Claude 3 Haiku...');
      const fallbackCommand = new InvokeModelCommand({
        modelId: "anthropic.claude-3-haiku-20240307-v1:0",
        contentType: "application/json",
        accept: "application/json",
        body: JSON.stringify(payload)
      });
      const response = await bedrockClient.send(fallbackCommand);
      const responseBody = JSON.parse(new TextDecoder().decode(response.body));
      const responseText = responseBody.content?.[0]?.text || '';
      return responseText.trim();
    }
    throw error;
  }
}

